# excavator_cfg.py
#
# The shared ArticulationCfg. Both tasks spawn the same machine with the same
# actuators; only observations, actions and rewards differ.

from __future__ import annotations

import math
from pathlib import Path

import isaaclab.sim as sim_utils
from isaaclab.actuators import ImplicitActuatorCfg
from isaaclab.assets import ArticulationCfg

from .excavator import (
    ARM_RANGE,
    JOINT_ARMS,
    JOINT_DRUMS,
    JOINT_SHROUDS,
    JOINT_WHEELS,
    CHASSIS_Z,
    ROTOR_TIP_R,
    source_hash,
    source_stamp_path,
)

# Generated by the offline MJCF -> USD converter. MjcfConverter keeps only
# the output argument's directory and names the file
# "<input stem>/<input stem>.usda", so an output argument of
# <repo>/assets/excavator.usd lands at <repo>/assets/excavator/excavator.usda.
ASSETS_DIR = Path(__file__).resolve().parents[2] / "assets"
EXCAVATOR_USD_PATH = ASSETS_DIR / "excavator" / "excavator.usda"

# ---------------------------------------------------------------------------
# Prim paths
# ---------------------------------------------------------------------------
#
# The converter nests every body under Geometry/<root body>, and a child of a
# child (the drums hang off the arms) one level deeper, which the `.*`
# absorbs. scripts/run_task.py prints the real paths.
EXCAVATOR_PRIM = "{ENV_REGEX_NS}/Excavator"
CHASSIS_PRIM = EXCAVATOR_PRIM + "/Geometry/chassis"
# Coupler configs take expanded regexes.
EXCAVATOR_PRIM_REGEX = r"/World/envs/env_.*/Excavator"
# Wheels, rotors and shrouds. The shroud is what retains the load.
SOIL_CONTACT_BODIES_REGEX = (
    r"/World/envs/env_.*/Excavator/Geometry/chassis/"
    r".*(wheel_.._body|drum_(front|rear)_body|shroud_(front|rear)_body)"
)

# The running gear alone. Wheels carry the machine and the drums do not, so the
# two want different effective masses presented to the MPM solve and therefore
# separate proxy mappings. See wheel_proxy_mass_scale in excavate_env_cfg.
WHEEL_CONTACT_BODIES_REGEX = (
    r"/World/envs/env_.*/Excavator/Geometry/chassis/"
    r".*(wheel_.._body)"
)

# The cutting end alone: rotors and shrouds, no wheels.
#
# The implicit MPM soil develops no footing bearing capacity. A parked machine
# -- wheels commanded to zero, arm stowed, drums never touching soil -- sinks
# until it rests on the bed floor, and that is not a configuration problem:
# the proxy feedback is right (the harvested wheel impulses sum to 820 N
# against a weight of 797 N), and it survives every material parameter, every
# proxy mode, particles per cell, grid resolution and bed depth. The same
# failure reproduces in the upstream two-way coupling example on its own
# published parameters, where the sand carries a 7x to 17x margin on paper.
#
# So the wheels come out of the soil coupling and ride rigid rails instead,
# which the excavate scene places under each track. Wheel-terrain interaction
# is then rigid contact and carries no sinkage; the soil the drums cut is
# still MPM, which is the part the dig policy is learning.
#
# The rails are placed clear of the cut rather than merely alongside it. The
# rotor ends at ROTOR_HALF_LEN = 0.475 and a tyre's inboard edge begins at
# exactly the same y, but the shroud end plates close the pockets 12 mm
# further out, so the cutting end reaches 0.487 and genuinely overlaps the
# wheel band: what keeps the two apart on the machine is separation in x, as
# noted where the arms are laid out. A rail has no x separation to rely on, so
# the excavate cfg pulls its inner face outboard of 0.487 by more than two
# collider margins and scripts/rail_check.py asserts the gap.
DRUM_CONTACT_BODIES_REGEX = (
    r"/World/envs/env_.*/Excavator/Geometry/chassis/"
    r".*(drum_(front|rear)_body|shroud_(front|rear)_body)"
)

# Wheels rest on z = 0 with the chassis origin one wheel radius up; the extra
# 2 cm keeps the solver off an initial interpenetration.
SPAWN_Z = CHASSIS_Z + 0.02

# Held during navigation, clear of the ground.
ARM_STOW_ANGLE = ARM_RANGE[0]


# ---------------------------------------------------------------------------
# Gravity
# ---------------------------------------------------------------------------
#
# Set on SimulationCfg.gravity in every env cfg.
LUNAR_GRAVITY = (0.0, 0.0, -1.62)
EARTH_G = 9.81
LUNAR_G = 1.62

# Weight scales with gravity, regolith cohesion and shear strength do not.
# The machine's 492 kg weighs 797 N here against 4824 N on Earth, so total
# tractive force at mu = 1 is ~797 N and a drum cutting a 1 m swath can exceed
# that alone. The two drums turn opposite ways so their horizontal reactions
# cancel through the frame; the drift reward term measures the cancellation.

# Wheel speed, capped below actuator capability. The machine is
# traction-limited on regolith before it is torque-limited.
MAX_WHEEL_SPEED = 5.0       # rad/s  -> 1.5 m/s at r = 0.30
MAX_YAW_SPEED = 3.0         # rad/s differential added across the two sides

# Outward acceleration at the vane tips is omega^2 * ROTOR_TIP_R, which
# reaches lunar gravity at 2.96 rad/s. The cap sits under it, at 28 rpm, where
# terrestrial bucket wheels run.
MAX_DRUM_SPEED = 2.9        # rad/s
SPIN_LIMIT = math.sqrt(LUNAR_G / ROTOR_TIP_R)


# Actuator effort ceilings. The actuator cfgs below take these, and the
# observation divides measured joint torque by them.
WHEEL_EFFORT = 120.0
# 800 let the arms jack the whole machine off its wheels. Commanded to a cut
# depth, the shroud reached soil, the actuator found that lifting a 797 N rover
# was cheaper than cutting, and the chassis ROSE 53 mm with all four wheels
# ending 73 mm clear of the bed and carrying nothing -- the entire 816 N of
# support came through the two shrouds. No wheels on the ground means no
# traction, no forward motion, and so no cutting: the drums only press.
#
# Torque PER ARM to lift the machine is (W/2) * ARM_LEN * cos(angle), lowest at
# the full dig angle:
#
#     angle -0.55 (stow)   258 N.m
#     angle  0.00          303 N.m
#     angle +0.72 (dig)    228 N.m   <- the floor; stay below this
#
# Holding the empty drum, shroud and arm out needs 67 N.m, so the usable window
# is 67 .. 228. 180 sits in it at 2.7x the hold and 0.79x the lift threshold.
#
# Note what does NOT fit in that window: holding a FULL drum out horizontally
# is the 229 N.m this file already quoted, and even at the dig angle it is
# about 200 N.m. Both are at or above the 228 N.m that lifts the machine, so
# there is NO effort limit at which this rover both carries a full drum on an
# extended arm and stays on its wheels. That is a machine design problem --
# 492 kg at lunar gravity is 797 N against a 0.76 m arm -- and the answers are a
# heavier rover, a shorter arm, or a lower target_load_kg. It is recorded here
# rather than hidden behind a large effort limit, which is what 800 was doing.
ARM_EFFORT = 180.0
DRUM_EFFORT = 350.0
SHROUD_EFFORT = 200.0


def usd_status() -> str | None:
    """None if the converted asset is present and newer than its source,
    else a message naming the fix."""
    source = Path(__file__).with_name("excavator.py")
    rebuild = (
        "  rebuild it (from the Isaac Lab directory):\n"
        '    isaaclab -p -c "from luna_hifi_tasks.excavator.excavator import write_mjcf;'
        ' print(write_mjcf())"\n'
        f"    rm -rf {ASSETS_DIR / 'excavator'}\n"
        f"    isaaclab -p scripts/tools/convert_mjcf.py <that path> {ASSETS_DIR / 'excavator.usd'}\n"
        "  note the output path: assets/excavator.usd, not assets/excavator/excavator.usd"
    )
    if not EXCAVATOR_USD_PATH.exists():
        return f"the excavator asset is missing:\n    {EXCAVATOR_USD_PATH}\n{rebuild}"
    # Content first. The mtime test below cannot see the case that actually
    # bites: `git checkout -- .` and `git pull` rewrite excavator.py AND the
    # tracked excavator.usd in the same instant, so source is not newer and a
    # stale asset sails through. That cost a dig run -- ROTOR_VANES went 6 -> 4
    # and the drum in the probe still reported 31 geoms, which is 6 vanes x 5
    # segments plus a hub. The stamp is written beside the USD by write_mjcf
    # and tracked with it, so a pull that restores a stale asset restores its
    # stale stamp too and the mismatch survives.
    try:
        stamp = source_stamp_path()
        if stamp.exists():
            if stamp.read_text().strip() != source_hash():
                return (
                    f"excavator.py does not match the converted asset: its source hash\n"
                    f"  is {source_hash()} and the asset was built from\n"
                    f"  {stamp.read_text().strip()}. This run would use the previous\n"
                    f"  geometry:\n    {EXCAVATOR_USD_PATH}\n{rebuild}"
                )
            return None
    except OSError:
        pass

    if source.exists() and source.stat().st_mtime > EXCAVATOR_USD_PATH.stat().st_mtime:
        return (
            f"excavator.py is NEWER than the converted asset, so this run would use the\n"
            f"  previous geometry:\n"
            f"    {EXCAVATOR_USD_PATH}\n{rebuild}"
        )
    # No stamp and no mtime complaint. write_mjcf has not run since the stamp
    # was introduced, so the only check standing is the one that git defeats.
    if not source_stamp_path().exists():
        return (
            f"the converted asset carries no source stamp, so it cannot be checked\n"
            f"  against excavator.py. The mtime test that remains is defeated by any\n"
            f"  git checkout. Rebuild once to establish it:\n{rebuild}"
        )
    return None


EXCAVATOR_CFG = ArticulationCfg(
    prim_path="{ENV_REGEX_NS}/Excavator",
    spawn=sim_utils.UsdFileCfg(usd_path=str(EXCAVATOR_USD_PATH)),
    init_state=ArticulationCfg.InitialStateCfg(
        pos=(0.0, 0.0, SPAWN_Z),
        # (x, y, z, w), Isaac Lab 3.x order. Identity is (0, 0, 0, 1).
        rot=(0.0, 0.0, 0.0, 1.0),
        joint_pos={".*": 0.0},
        joint_vel={".*": 0.0},
    ),
    actuators={
        # Velocity drive, traction-sized for lunar gravity. ~123 kg per wheel
        # is ~199 N of normal force at 1.62 m/s^2, so ~60 N-m at r = 0.30
        # before slip, and the 120 ceiling is a 2x margin.
        #
        # With stiffness 0 the damping is the gain: torque is damping times
        # the velocity error. At 400 the drive reaches the effort limit at a
        # 0.3 rad/s error, so it acts as a torque source up to the ceiling at
        # any commanded speed, including the crawl a cut runs at. Tractive
        # force is bounded by effort_limit_sim and the ground.
        "wheels": ImplicitActuatorCfg(
            joint_names_expr=JOINT_WHEELS,
            effort_limit_sim=WHEEL_EFFORT,
            velocity_limit_sim=12.0,
            stiffness=0.0,
            damping=400.0,
        ),
        # Position drive, force-limited so it cannot lift the machine. See
        # ARM_EFFORT above for the window. Do NOT raise this past 228 N.m to
        # cure a sagging arm: above that the actuator stops cutting and starts
        # jacking the rover onto its shrouds, which reads as a machine that
        # cannot excavate. If the arm sags under load, the load is too large
        # for the arm -- lower target_load_kg or shorten ARM_LEN.
        "arms": ImplicitActuatorCfg(
            joint_names_expr=JOINT_ARMS,
            effort_limit_sim=ARM_EFFORT,
            velocity_limit_sim=1.5,
            stiffness=2500.0,
            damping=250.0,
        ),
        # Velocity drive. Cutting torque follows soil strength. Raise if a
        # rotor stalls in soil.
        "drums": ImplicitActuatorCfg(
            joint_names_expr=JOINT_DRUMS,
            effort_limit_sim=DRUM_EFFORT,
            velocity_limit_sim=6.0,
            stiffness=0.0,
            damping=40.0,
        ),
        # Position drive. The retained load presses outward, mostly radially,
        # and what the shroud holds about the axis is the asymmetry of a
        # part-full drum, about 40 N-m at capacity. 200 is a 5x margin.
        "shrouds": ImplicitActuatorCfg(
            joint_names_expr=JOINT_SHROUDS,
            effort_limit_sim=SHROUD_EFFORT,
            velocity_limit_sim=2.0,
            stiffness=1500.0,
            damping=150.0,
        ),
    },
)
